using System.IO;
using System.Windows;
using Windows.Win32;
using Windows.Win32.UI.WindowsAndMessaging;

namespace Chippi.App.Tray;

/// <summary>
/// Builds the tray HICON from Tray/Assets/chippi.ico (a WPF resource, generated by make_icon.py):
/// the frame nearest the requested size, the larger one on a tie, scaled to that size.
/// </summary>
internal static class TrayIconImage
{
    private static readonly Uri IconUri = new("pack://application:,,,/Tray/Assets/chippi.ico", UriKind.Absolute);

    private static byte[]? _ico;

    public static unsafe HICON Create(int size)
    {
        var ico = _ico ??= Load();

        // ICONDIR (6 bytes), then one 16-byte ICONDIRENTRY per frame: width, height, colors,
        // reserved, planes, bit count, byte count, offset. A width byte of 0 means 256.
        int count = BitConverter.ToUInt16(ico, 4);
        int best = 0, bestWidth = 0;
        for (int i = 0; i < count; i++)
        {
            int width = ico[6 + (16 * i)] is 0 ? 256 : ico[6 + (16 * i)];
            int distance = Math.Abs(width - size), bestDistance = Math.Abs(bestWidth - size);
            if (i == 0 || distance < bestDistance || (distance == bestDistance && width > bestWidth))
                (best, bestWidth) = (i, width);
        }

        int entry = 6 + (16 * best);
        int length = BitConverter.ToInt32(ico, entry + 8);
        int offset = BitConverter.ToInt32(ico, entry + 12);
        fixed (byte* bits = &ico[offset])
        {
            // 0x00030000: the icon resource format version CreateIconFromResourceEx expects.
            return PInvoke.CreateIconFromResourceEx(bits, (uint)length, true, 0x00030000, size, size, IMAGE_FLAGS.LR_DEFAULTCOLOR);
        }
    }

    private static byte[] Load()
    {
        var info = Application.GetResourceStream(IconUri)
            ?? throw new InvalidOperationException($"Missing resource {IconUri}");
        using var stream = info.Stream;
        using var memory = new MemoryStream();
        stream.CopyTo(memory);
        return memory.ToArray();
    }
}
